constexpr int N = 2e6 + 10;
constexpr int mod = 998244353;

ll fac[N], invfac[N];
ll A(int n, int m)
{
	if (m < 0 || m > n)return 0;
	return fac[n] * invfac[n - m] % mod;
}
void init()
{
	fac[0] = invfac[0] = 1;
	fa(i, 1, N - 1)fac[i] = fac[i - 1] * i % mod;
	invfac[N - 1] = Math::fastPow(fac[N - 1], mod - 2, mod);
	fb(i, N - 2, 1)invfac[i] = invfac[i + 1] * (i + 1) % mod;
}
void solve(int CASE)
{
	int n, q; cin >> n >> q;
	int len = 1 << n;                       // 叶子个数
	var x = vector<int>(2 * len + 1);       // 每个点上被钦定的值
	var mp = map<int, VI>();                // 值 -> 被钦定为该值的所有点

	fa(_, 1, q) {
		int u, k; cin >> u >> k;
		mp[k].pb(u);
		if (x[u] and x[u] != k) {           // 同一个点被钦定成两个不同的值
			cout << 0 << endl;
			return;
		}
		x[u] = k;
	}

	// 值相同的点必须两两有祖孙关系, 按编号排序后只用判相邻的
	for (var& [k, ve] : mp) {
		sort(all(ve));
		fa(i, 1, vs(ve)) {
			int now = ve[i];
			while (now and now != ve[i - 1])now >>= 1;
			if (now != ve[i - 1]) {
				cout << 0 << endl;
				return;
			}
		}
	}

	var val = vector<int>(len + 1);           // 叶子的可能取值
	var mxv = vector<int>(len + 1, len + 1);  // 叶子取值的上界
	bool ok = true;

	var dfs = [&](var dfs, int now, int l, int r)->void {
		if (l == r) {
			if (x[now])val[l] = mxv[l] = x[now];
			return;
		}

		int mid = (l + r) >> 1;
		dfs(dfs, now << 1, l, mid);
		dfs(dfs, now << 1 | 1, mid + 1, r);
		if (!x[now])return;

		bool has = 0;
		int cnt = 0; // 有效空位数
		fa(i, l, r) {
			if (val[i] > x[now])ok = 0;
			if (val[i] == x[now])has = 1;
			if (!val[i] and mxv[i] >= x[now])cnt++;
			mxv[i] = min(mxv[i], x[now]);
		}
		if (!has) {
			if (!cnt)ok = 0;
			fa(i, l, r)
				if (!val[i] and mxv[i] >= x[now])
					val[i] = x[now];
		}
		};
	dfs(dfs, 1, 1, len);

	if (!ok) {
		cout << 0 << endl;
		return;
	}

	var c = vector<int>(len + 2);   // c[v]: 取值可能为 v 的叶子数
	var t = vector<int>(len + 2);   // t[v]: 上界是 v 的叶子数
	fa(i, 1, len)c[val[i]]++, t[mxv[i]]++;

	ll ans = 1;
	int num = 0;
	fa(v, 1, len) {
		num++;
		if (!t[v])continue;
		if (num < t[v]) { // 值不够填
			cout << 0 << endl;
			return;
		}
		if (c[v])ans = ans * c[v] % mod * A(num - 1, t[v] - 1) % mod;
		else ans = ans * A(num, t[v]) % mod;
		num -= t[v];
	}
	cout << ans * A(num, num) % mod << endl;
	return;
}
